/**
 * Stages 13/15 — wallpapers for each battlefield.
 * The manifest is generated by scripts/sync_wallpapers.py before image build.
 * Important: player components are morphed on game actions. Never attach
 * wallpaper attributes or styles to .battlefield-canvas: morphAttributes()
 * removes properties that are absent from the authoritative server HTML.
 * Instead, write both images once to #players-area, which is OUTSIDE the
 * player component refresh targets. CSS assigns them to each seat by role.
 * Missing/empty manifest is intentionally harmless.
 */
const WALLPAPER_MANIFEST = '/assets/wallpapers/manifest.json'

export function chooseStage13Wallpaper(files, used = new Set(), random = Math.random) {
  const allowed = files.filter((name) => typeof name === 'string' &&
    !name.includes('/') && !name.includes('\\') &&
    !name.startsWith('.') && /\.(?:jpe?g|png)$/i.test(name))
  const unused = allowed.filter((name) => !used.has(name))
  const choices = unused.length ? unused : allowed
  if (!choices.length) return null
  const r = Number(random())
  const index = Number.isFinite(r) ? Math.min(choices.length - 1, Math.max(0, Math.floor(r * choices.length))) : 0
  return choices[index]
}

export function mountStage13Wallpapers(game, manifestUrl = WALLPAPER_MANIFEST) {
  // #players-area exists on the initial table page, even if only one player
  // has joined. Component updates replace its children, but not this node.
  const area = game?.querySelector('#players-area')
  if (!area) return () => {}

  let disposed = false
  fetch(manifestUrl, { cache: 'no-store' })
    .then((response) => response.ok ? response.json() : [])
    .then((data) => {
      if (disposed || !Array.isArray(data)) return
      const own = chooseStage13Wallpaper(data)
      if (!own) return
      const opponent = chooseStage13Wallpaper(data, new Set([own]))
      const wallpaperUrl = (filename) =>
        `url("/assets/wallpapers/${encodeURIComponent(filename)}")`

      // Persistent parent variables are inherited by newly created/morphed
      // battlefield canvases. No MutationObserver, reapply loop or repaint
      // triggered by card actions is necessary.
      area.style.setProperty('--stage13-wallpaper-own', wallpaperUrl(own))
      area.style.setProperty('--stage13-wallpaper-opponent', wallpaperUrl(opponent ?? own))
      area.setAttribute('data-stage13-wallpapers-ready', '')
    })
    .catch(() => {}) // A missing manifest should not block gameplay.

  return () => { disposed = true }
}

/**
 * Stage 14 — choose one wallpaper for the initial create/join-table page.
 * Use the existing JPG/JPEG/PNG manifest. This changes only the page's
 * appearance; Cloudflare Access and application sessions are unaffected.
 */
export function mountStage14LobbyWallpaper(lobby, manifestUrl = WALLPAPER_MANIFEST) {
  if (!lobby) return
  fetch(manifestUrl, { cache: 'no-store' })
    .then((response) => response.ok ? response.json() : [])
    .then((files) => {
      if (!lobby.isConnected || !Array.isArray(files)) return
      const name = chooseStage13Wallpaper(files)
      if (!name) return
      const url = `/assets/wallpapers/${encodeURIComponent(name)}`
      document.body.style.setProperty('--stage14-lobby-wallpaper', `url("${url}")`)
      document.body.classList.add('stage14-lobby-background')
    })
    .catch(() => {}) // Missing wallpaper assets never block the lobby.
}
